<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {api,day,fmt} from '@/lib/api';import PageHeader from '@/components/PageHeader.vue';import EmptyState from '@/components/EmptyState.vue';const items=ref<any[]>([]),filter=ref('all');const shown=computed(()=>items.value.filter(x=>filter.value==='zero'?x.totalQuantity===0:filter.value==='low'?x.totalQuantity>0&&x.totalQuantity<=5:true));onMounted(async()=>items.value=await api('/inventory'))</script>
<template><PageHeader title="库存批次" subtitle="当前库存按采购批次的实际产品与包材成本估值"><el-segmented v-model="filter" :options="[{label:'全部库存',value:'all'},{label:'低库存 ≤5',value:'low'},{label:'零库存',value:'zero'}]"/></PageHeader><div class="space-y-4"><el-card v-for="p in shown" :key="p.id" shadow="never" body-class="!p-0"><div class="flex flex-wrap items-center justify-between gap-4 p-5"><div><h3 class="font-bold">{{p.name}} <el-tag class="ml-2" effect="plain" type="info">{{p.sku}}</el-tag></h3><div class="mt-1 text-xs text-slate-500">{{p.category||'未分类'}}</div></div><div class="flex gap-10"><el-statistic title="可用库存" :value="p.totalQuantity"/><el-statistic title="库存价值" :value="p.inventoryValue" :precision="2" prefix="¥ "/></div></div><el-table :data="p.batches" stripe><el-table-column label="采购日期" width="120"><template #default="{row}">{{day(row.purchase.purchaseDate)}}</template></el-table-column><el-table-column label="订单号" prop="purchase.purchaseOrderNo"/><el-table-column label="厂家" prop="purchase.supplier"/><el-table-column label="入库" prop="quantity"/><el-table-column label="已售"><template #default="{row}">{{row.quantity-row.remainingQuantity}}</template></el-table-column><el-table-column label="剩余"><template #default="{row}"><b>{{row.remainingQuantity}}</b></template></el-table-column><el-table-column label="产品单价"><template #default="{row}">¥ {{fmt(row.productUnitCost)}}</template></el-table-column><el-table-column label="包材单价"><template #default="{row}">¥ {{fmt(row.packagingUnitCost)}}</template></el-table-column><el-table-column label="综合单价"><template #default="{row}">¥ {{fmt(Number(row.productUnitCost)+Number(row.packagingUnitCost))}}</template></el-table-column><el-table-column label="剩余价值"><template #default="{row}"><b>¥ {{fmt(row.remainingQuantity*(Number(row.productUnitCost)+Number(row.packagingUnitCost)))}}</b></template></el-table-column></el-table></el-card><el-empty v-if="!shown.length" description="暂无库存数据"/></div></template>
